SELECT budget_bucket, pct_legal, total_budget FROM (SELECT CASE WHEN budget >= 4327000 THEN 'high' WHEN budget >= 1027000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN dept_name = 'Legal' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_legal, SUM(budget) AS total_budget FROM departments GROUP BY CASE WHEN budget >= 4327000 THEN 'high' WHEN budget >= 1027000 THEN 'mid' ELSE 'low' END) AS t WHERE pct_legal >= 29 ORDER BY 3 DESC, budget_bucket DESC;
